package org.example.skillsprint.controller;

import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import jakarta.servlet.http.HttpSession;
import org.example.skillsprint.dao.GoalDAO;import org.example.skillsprint.model.Goal;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.web.bind.annotation.*;
import java.io.IOException;import java.sql.Date;import java.sql.SQLException;import java.time.LocalDate;import java.time.format.DateTimeParseException;import java.util.Arrays;import java.util.List;

@Controller @RequestMapping("/goals")
public class GoalController {
    private static final List<String> STATUSES=Arrays.asList("Pending","Completed");private final GoalDAO dao;public GoalController(GoalDAO dao){this.dao=dao;}
    @GetMapping({"","/","/list"}) public String list(@RequestParam(name="status",required=false) String status,Model m,HttpServletRequest req,HttpServletResponse res){if(status!=null&&!status.isEmpty()&&!STATUSES.contains(status))status="";try{m.addAttribute("goals",status==null||status.isEmpty()?dao.listForUser(uid(req)):dao.listForUser(uid(req),status));m.addAttribute("statuses",STATUSES);m.addAttribute("selectedStatus",status==null?"":status);return "goal-list";}catch(SQLException e){return error(m,res);}}
    @GetMapping("/new") public String newForm(Model m){Goal g=new Goal();g.setStatus("Pending");return form(m,g,false,null,null);}
    @GetMapping("/edit") public String edit(@RequestParam("id") String id,Model m,HttpServletRequest req,HttpServletResponse res) throws IOException {Integer i=parse(id);if(i==null){res.sendError(400,"Invalid goal ID.");return null;}try{Goal g=dao.findForUser(i,uid(req));if(g==null){res.sendError(404,"Goal not found.");return null;}return form(m,g,true,null,null);}catch(SQLException e){return error(m,res);}}
    @PostMapping("/create") public String create(@RequestParam(name="goalTitle",defaultValue="") String goalTitle,@RequestParam(name="deadline",required=false) String deadline,@RequestParam(name="status",defaultValue="") String status,Model m,HttpServletRequest req,HttpServletResponse res) throws IOException {return save(0,false,goalTitle,deadline,status,m,req,res);}
    @PostMapping("/update") public String update(@RequestParam("id") String id,@RequestParam(name="goalTitle",defaultValue="") String goalTitle,@RequestParam(name="deadline",required=false) String deadline,@RequestParam(name="status",defaultValue="") String status,Model m,HttpServletRequest req,HttpServletResponse res) throws IOException {Integer i=parse(id);if(i==null){res.sendError(400,"Invalid goal ID.");return null;}return save(i,true,goalTitle,deadline,status,m,req,res);}
    @PostMapping("/complete") public String complete(@RequestParam("id") String id,HttpServletRequest req,HttpServletResponse res,Model m) throws IOException {Integer i=parse(id);if(i==null){res.sendError(400,"Invalid goal ID.");return null;}try{if(!dao.markCompleted(i,uid(req))){res.sendError(404,"Goal not found.");return null;}return "redirect:/goals/list";}catch(SQLException e){return error(m,res);}}
    @PostMapping("/delete") public String delete(@RequestParam("id") String id,HttpServletRequest req,HttpServletResponse res,Model m) throws IOException {Integer i=parse(id);if(i==null){res.sendError(400,"Invalid goal ID.");return null;}try{if(!dao.delete(i,uid(req))){res.sendError(404,"Goal not found.");return null;}return "redirect:/goals/list";}catch(SQLException e){return error(m,res);}}
    private String save(int id,boolean edit,String title,String raw,String status,Model m,HttpServletRequest req,HttpServletResponse res) throws IOException {int user=uid(req);Goal g=new Goal();g.setGoalId(id);g.setUserId(user);g.setGoalTitle(title.trim());g.setStatus(status.trim());String d=trim(raw);if(!d.isEmpty())try{g.setDeadline(Date.valueOf(LocalDate.parse(d)));}catch(DateTimeParseException ignored){}String e=validate(g,raw);if(e!=null)return form(m,g,edit,e,raw);try{if(edit){if(!dao.update(g,user)){res.sendError(404,"Goal not found.");return null;}}else dao.create(g);return "redirect:/goals/list";}catch(SQLException ex){return error(m,res);}}
    private String validate(Goal g,String raw){if(g.getGoalTitle().isEmpty())return "Goal title is required.";if(g.getGoalTitle().length()>200)return "Goal title must be 200 characters or fewer.";if(!STATUSES.contains(g.getStatus()))return "Choose Pending or Completed for status.";if(raw!=null&&!raw.trim().isEmpty()&&g.getDeadline()==null)return "Enter a valid deadline.";return null;}
    private String form(Model m,Goal g,boolean edit,String error,String raw){m.addAttribute("goal",g);m.addAttribute("editMode",edit);m.addAttribute("statuses",STATUSES);m.addAttribute("error",error);m.addAttribute("rawDeadline",raw);return "goal-form";}
    private String error(Model m,HttpServletResponse r){r.setStatus(500);m.addAttribute("error","The goal could not be saved or loaded. Please try again.");return "goal-error";}
    private int uid(HttpServletRequest r){HttpSession s=r.getSession(false);Object v=s==null?null:s.getAttribute("userId");return v instanceof Number?((Number)v).intValue():0;}
    private Integer parse(String s){try{return s!=null&&s.matches("[1-9][0-9]{0,9}")?Integer.valueOf(s):null;}catch(NumberFormatException e){return null;}}private String trim(String s){return s==null?"":s.trim();}
}
